import{_ as t}from"./chunks/string_job.D9CE2ynq.js";import{_ as o,o as a,c as i,a0 as n}from"./chunks/framework.akKRIpjQ.js";const m=JSON.parse('{"title":"04 · Stringing Log","description":"","frontmatter":{},"headers":[],"relativePath":"guide/04-stringing-log.md","filePath":"guide/04-stringing-log.md"}'),r={name:"guide/04-stringing-log.md"};function s(l,e,d,h,c,u){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="_04-·-stringing-log" tabindex="-1">04 · Stringing Log <a class="header-anchor" href="#_04-·-stringing-log" aria-label="Permalink to &quot;04 · Stringing Log&quot;">​</a></h1><blockquote><p>Feature 3 of 4. One record per restring + auto reminder when it&#39;s time.</p></blockquote><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><img src="'+t+`" alt="Adding a stringing record" style="max-width:320px;border-radius:12px;margin:12px 0;"><p>A &quot;stringing log&quot; tab on each racket&#39;s <a href="./03-racquets.html#detail-page">detail page</a>. Each entry is one restring:</p><ul><li>Date</li><li>String model (main + cross)</li><li>Tension (main / cross)</li><li>Stringer (optional)</li><li>Notes</li><li><strong>Source</strong> — &quot;Manual&quot; / &quot;From <a href="./05-tension-conversion.html">05 · Tension conversion</a>&quot; (if entered via that handoff)</li></ul><p>The latest record&#39;s date also drives the racket&#39;s &quot;last restring&quot; stamp on the list page.</p><h2 id="add-a-stringing-record" tabindex="-1">Add a stringing record <a class="header-anchor" href="#add-a-stringing-record" aria-label="Permalink to &quot;Add a stringing record&quot;">​</a></h2><ol><li>Open the racket → <code>Stringing log</code> tab → <code>+ Add stringing record</code></li><li>Fill the form:</li></ol><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>Date</td><td>Today</td><td>Past dates are also OK</td></tr><tr><td>String main</td><td>empty</td><td>Dropdown with our preset string library (Yonex BG65 / BG80, Wilson NXT, polyester series, etc.); can be custom</td></tr><tr><td>String cross</td><td>empty</td><td>Optional — leave blank for a single-string setup</td></tr><tr><td>Tension main</td><td>(inherits from racket profile)</td><td>lbs or kg; can override</td></tr><tr><td>Tension cross</td><td>(inherits)</td><td>Optional</td></tr><tr><td>Stringer</td><td>empty</td><td>Free text</td></tr><tr><td>Notes</td><td>empty</td><td>&quot;2 overgrip layers / 1 dampener / strung 30 min&quot;</td></tr><tr><td>Source</td><td><code>Manual</code></td><td>Set automatically to &quot;From Tension conversion&quot; if you came in via <a href="./05-tension-conversion.html">chapter 05</a></td></tr></tbody></table><ol start="3"><li><code>Save</code></li></ol><blockquote><p><strong>Don&#39;t know the string model?</strong> Open <code>Stringing log → String library</code> for our preset list of a few hundred items; can be custom too.</p></blockquote><h2 id="the-stringing-library" tabindex="-1">The stringing library <a class="header-anchor" href="#the-stringing-library" aria-label="Permalink to &quot;The stringing library&quot;">​</a></h2><p>The dropdown is backed by an offline string database:</p><ul><li>Brand: Yonex, Wilson, Babolat, Head, Prince, Luxilon, Tecnifibre, …</li><li>Type: multifilament / polyester / natural gut / hybrid</li><li>For each: typical play life (hours), recommended tension range</li></ul><blockquote><p>Filtering by type lets you see only what you&#39;ve actually used.</p></blockquote><h2 id="reminders" tabindex="-1">Reminders <a class="header-anchor" href="#reminders" aria-label="Permalink to &quot;Reminders&quot;">​</a></h2><h3 id="mode-a-·-by-time" tabindex="-1">Mode A · By time <a class="header-anchor" href="#mode-a-·-by-time" aria-label="Permalink to &quot;Mode A · By time&quot;">​</a></h3><p>Simplest: remind every N days.</p><ul><li>Pick N (default 90, options 30 / 60 / 90 / 120 / 180)</li><li>Pick reminder time window (default <code>09:00</code>)</li><li>On trigger, the App auto-archives the &quot;last restring&quot; date, and the next reminder counts from that day</li></ul><h3 id="mode-b-·-by-play-hours" tabindex="-1">Mode B · By play hours <a class="header-anchor" href="#mode-b-·-by-play-hours" aria-label="Permalink to &quot;Mode B · By play hours&quot;">​</a></h3><p>More granular: estimate your weekly sessions × duration → total play hours; fire when you reach a target (e.g. 80 hours).</p><ul><li>Weekly play frequency (sessions)</li><li>Average session duration (hours)</li><li>Target play hours (default 80 hours / string; cross-string default 60 hours)</li><li><strong>String type coefficient</strong> (multifilament nylon 1.0; polyester 0.7; natural gut 0.5)</li></ul><blockquote><p>Example: 3 sessions / week × 2 hours = 6 h/week, nylon 1.0 → 80 / 6 ≈ 13 weeks ≈ 3 months.</p></blockquote><p>The App has a &quot;remind for main and cross separately&quot; toggle for Mode B.</p><h2 id="what-do-the-reminders-look-like" tabindex="-1">What do the reminders look like? <a class="header-anchor" href="#what-do-the-reminders-look-like" aria-label="Permalink to &quot;What do the reminders look like?&quot;">​</a></h2><p>Android system notification:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────┐</span></span>
<span class="line"><span>│ 🏸 AceCrush Craft        9:00 AM    │</span></span>
<span class="line"><span>│                                      │</span></span>
<span class="line"><span>│ &quot;Main Blade&quot; is due for restring     │</span></span>
<span class="line"><span>│ Last strung: 2026-04-15, 92d ago    │</span></span>
<span class="line"><span>│                                      │</span></span>
<span class="line"><span>│ [Snooze] [View] [Mark restringed]    │</span></span>
<span class="line"><span>└──────────────────────────────────────┘</span></span></code></pre></div><ul><li><code>Mark restringed</code> → jumps straight to &quot;Add stringing record&quot; (you fill the date, the old entry is auto-archived)</li><li><code>Snooze</code> → defer 24 hours</li><li><code>View</code> → racket detail page</li></ul><h2 id="common-questions" tabindex="-1">Common questions <a class="header-anchor" href="#common-questions" aria-label="Permalink to &quot;Common questions&quot;">​</a></h2><h3 id="can-the-tension-come-from-the-conversion-tool" tabindex="-1">Can the tension come from the conversion tool? <a class="header-anchor" href="#can-the-tension-come-from-the-conversion-tool" aria-label="Permalink to &quot;Can the tension come from the conversion tool?&quot;">​</a></h3><p>Yes! That&#39;s the whole point of <a href="./05-tension-conversion.html">05 · Tension conversion</a>. When you&#39;re on the conversion result screen, tap <strong>&quot;Use this tension → log stringing&quot;</strong>. The App jumps straight into &quot;Add stringing record&quot; with the tension pre-filled, the racket pre-selected, and the source marked as &quot;From Tension conversion&quot;.</p><h3 id="what-if-the-system-has-notifications-off" tabindex="-1">What if the system has notifications off? <a class="header-anchor" href="#what-if-the-system-has-notifications-off" aria-label="Permalink to &quot;What if the system has notifications off?&quot;">​</a></h3><p>Open system <code>Settings → Apps → AceCrush Craft → Notifications</code> and turn &quot;Allow&quot; back on. Then in the App, <code>Me → Notifications &amp; reminders</code> reset all toggles.</p><h3 id="where-do-the-strings-live" tabindex="-1">Where do the strings live? <a class="header-anchor" href="#where-do-the-strings-live" aria-label="Permalink to &quot;Where do the strings live?&quot;">​</a></h3><p>Offline in the App. They update alongside the App release; you can also add custom models.</p><h3 id="i-restring-the-same-racket-twice-in-a-month-—-record-both" tabindex="-1">I restring the same racket twice in a month — record both? <a class="header-anchor" href="#i-restring-the-same-racket-twice-in-a-month-—-record-both" aria-label="Permalink to &quot;I restring the same racket twice in a month — record both?&quot;">​</a></h3><p>Yes. Each is its own entry. The reminder defaults to the latest one.</p><h2 id="deleting-a-racket" tabindex="-1">Deleting a racket <a class="header-anchor" href="#deleting-a-racket" aria-label="Permalink to &quot;Deleting a racket&quot;">​</a></h2><p>Detail page → top-right <code>···</code> → <code>Delete racket</code>.</p><blockquote><p>Deleting also <strong>wipes all of its stringing records</strong> (no dangling data). Reminder again: this is <strong>on this device only</strong> — back up via <code>Settings → Export → JSON</code> first.</p></blockquote>`,41)])])}const f=o(r,[["render",s]]);export{m as __pageData,f as default};
